#!/usr/bin/env node
// Builds scripts/preview.bundle.mjs: the preview CLI with its dependencies and templates inlined, so an agent that can run
// commands needs only Node, not `npm ci`. Also writes the third-party notices for the bundled packages beside it.
// Development only (esbuild is a devDependency). tests/bundle.test.mjs checks that the committed files match a fresh build.
import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
export const BUNDLE = join(root, 'scripts/preview.bundle.mjs');
export const NOTICES = join(root, 'scripts/preview.bundle.NOTICES.txt');
const BANNER = '// Generated by `npm run bundle` from scripts/preview.mjs. Do not edit; third-party notices: preview.bundle.NOTICES.txt';

/** The bundle and notices as strings, without writing anything. */
export async function build() {
  const esbuild = await import('esbuild');
  // absWorkingDir pins the source-path comments esbuild writes, so the output does not depend on the caller's directory.
  const result = await esbuild.build({
    absWorkingDir: root, entryPoints: ['scripts/preview.mjs'], bundle: true, platform: 'node', format: 'esm', target: 'node20',
    write: false, metafile: true, legalComments: 'none', banner: { js: BANNER }, logLevel: 'silent',
  });
  const bundle = result.outputFiles[0].text;
  // Every bundled npm package, with its license text, for redistribution.
  const packages = new Map();
  for (const input of Object.keys(result.metafile.inputs)) {
    const m = /node_modules\/((?:@[^/]+\/)?[^/]+)\//.exec(input);
    if (m && !packages.has(m[1])) packages.set(m[1], join(root, 'node_modules', m[1]));
  }
  const sections = [];
  for (const [name, dir] of [...packages].sort(([a], [b]) => a.localeCompare(b))) {
    const pkg = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
    const license = ['LICENSE', 'LICENSE.md', 'LICENSE.txt', 'license'].map(f => join(dir, f)).find(existsSync);
    sections.push(`${name}@${pkg.version} (${pkg.license})\n\n${license ? (await readFile(license, 'utf8')).trim() : 'No license file shipped; see the package metadata.'}`);
  }
  const notices = `Third-party software bundled into preview.bundle.mjs\n\n${sections.join('\n\n' + '-'.repeat(72) + '\n\n')}\n`;
  return { bundle, notices };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { bundle, notices } = await build();
  await writeFile(BUNDLE, bundle);
  await writeFile(NOTICES, notices);
  console.log(`wrote ${BUNDLE} (${bundle.length} bytes) and ${dirname(NOTICES)}/preview.bundle.NOTICES.txt`);
}
